type FileCache struct {
    mu sync.Locker // *sync.Mutex, or rw.RLocker() for the read-side policy
}

func (c *FileCache) Find(path string) (string, bool) {
    c.mu.Lock()
    defer c.mu.Unlock()          // scoped release on every path
    return c.findLocked(path)
}

// read-mostly policy: NewFileCache(rw.RLocker()) with a shared *sync.RWMutex
